INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(50111, 'Genesis 41:27', 'Genesis', 41, 27, 'اووه ډنګرې او بدرنګه غواګانې چې د هغو څخه وروسته راووتلې او د غلو دانو اووه نري او د دښتې باد سوځولي وږي د قحطۍ اووه کاله دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_27.mp3', '', 1761754199, 1761754199),
(50112, 'Genesis 41:28', 'Genesis', 41, 28, 'دا هماغه څه دي چې تاسو ته مې وویل. څه چې خدای غواړي ویې کړي، تاسو ته یې څرګند کړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_28.mp3', '', 1761754199, 1761754199),
(50113, 'Genesis 41:29', 'Genesis', 41, 29, 'اووه کاله به د مصر په ټول هېواد کې ډېره پرېماني راشي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_29.mp3', '', 1761754199, 1761754199),
(50114, 'Genesis 41:30', 'Genesis', 41, 30, 'خو له هغې وروسته به د اوو کالو دپاره داسې قحطي راشي چې د مصر په ملک کې به هغه ټوله پرېماني هېره شي، ځکه چې قحطي به هېواد تباه کړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_30.mp3', '', 1761754199, 1761754199),
(50115, 'Genesis 41:31', 'Genesis', 41, 31, 'او پرېماني به په هېواد کې بیخي هېره شي، ځکه چې هغه قحطي چې په هغې پسې راځي، هغه به ډېره سخته وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_31.mp3', '', 1761754199, 1761754199),
(50116, 'Genesis 41:32', 'Genesis', 41, 32, 'دا چې تاسو دوه خوبونه لیدلي دي، د هغو معنی دا ده چې دا د خدای پرېکړه ده چې دا کار وکړي او هغه به زر داسې وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_32.mp3', '', 1761754199, 1761754199),
(50117, 'Genesis 41:33', 'Genesis', 41, 33, 'اوس باید تاسو یو پوه او د حکمت لرونکی سړی پیدا کړئ او هغه د مصر د هېواد دوهم واکمن وټاکئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_33.mp3', '', 1761754199, 1761754199),
(50118, 'Genesis 41:34', 'Genesis', 41, 34, 'تاسو باید په ټول هېواد کې مامورین وټاکئ چې د اوو کالو پرېمانۍ په موده کې د مصر د حاصلاتو څخه پنځمه برخه راټوله کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_34.mp3', '', 1761754199, 1761754199),
(50119, 'Genesis 41:35', 'Genesis', 41, 35, 'هغوی ته امر وکړئ چې د پرېمانۍ په کلونو کې غله راټوله کړي او هغوی ته اختیار ورکړئ چې هغه په ښارونو کې ذخیره کړي او هغه وساتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_35.mp3', '', 1761754199, 1761754199),
(50120, 'Genesis 41:36', 'Genesis', 41, 36, 'هغه باید د هېواد دپاره ذخیره شي چې د اووه کالو د قحطۍ په موده کې چې په مصر باندې راتلونکې ده ورڅخه کار واخیستل شي، ترڅو هېواد د قحطۍ له امله وران نه شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_36.mp3', '', 1761754199, 1761754199),
(50121, 'Genesis 41:37', 'Genesis', 41, 37, 'دغه وړاندیز د فرعون او د هغه د ټولو درباریانو په نظر کې ښه ښکاره شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_37.mp3', '', 1761754199, 1761754199),
(50122, 'Genesis 41:38', 'Genesis', 41, 38, 'نو فرعون د هغوی څخه پوښتنه وکړه: «ایا کولای شو چې د یوسف په شان یو څوک راپیدا کړو چې د خدای روح په کې دی؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_38.mp3', '', 1761754199, 1761754199),
(50123, 'Genesis 41:39', 'Genesis', 41, 39, 'نو فرعون یوسف ته وویل: «څرنګه چې خدای دا هرڅه تاته ښودلي دي، نو ستا په شان د حکمت خاوند او پوه سړی نشته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_39.mp3', '', 1761754199, 1761754199),
(50124, 'Genesis 41:40', 'Genesis', 41, 40, 'زه به تا د خپل هېواد دوهم واکمن کړم او زما ټول قوم به ستا حکمونه مني او په واک کې به ته زما څخه وروسته دوهم کس یې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_40.mp3', '', 1761754199, 1761754199),
(50125, 'Genesis 41:41', 'Genesis', 41, 41, 'نو فرعون یوسف ته وویل: «په دې ډول مې ته د مصر د ټول هېواد دوهم واکمن وټاکلې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_41.mp3', '', 1761754199, 1761754199),
(50126, 'Genesis 41:42', 'Genesis', 41, 42, 'فرعون د خپلې ګوتې څخه هغه ګوته راوویستله چې په هغې کې د پاچاهۍ مهر لګېدلی ؤ او هغه یې یوسف ته ور په ګوته کړه. هغه یوسف ته د ډېر ښه کتان څخه یوه چپنه ورواغوستله او د سرو زرو زنځیر یې د هغه په غاړه کې واچاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_42.mp3', '', 1761754199, 1761754199),
(50127, 'Genesis 41:43', 'Genesis', 41, 43, 'فرعون هغه ته خپله دوهمه شاهي ګاډۍ ورکړه چې په کې سپور شي او خلکو د هغه په مخکې نارې وهلې: «لاره پرېږدئ! لاره پرېږدئ!» په دې ډول یې یوسف د مصر د ټول هېواد دوهم مشر وټاکه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_43.mp3', '', 1761754199, 1761754199),
(50128, 'Genesis 41:44', 'Genesis', 41, 44, 'فرعون یوسف ته وویل: «زه فرعون یم، خو هېڅوک به ستا له اجازې څخه پرته په ټول مصر کې هېڅ نه شي کولای.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_44.mp3', '', 1761754199, 1761754199),
(50129, 'Genesis 41:45', 'Genesis', 41, 45, 'فرعون په یوسف باندې صفنات فعنیح نوم کېښود او د اون د کاهن فوطي‌فارع لور اسنات یې هغه ته په نکاح ورکړه. نو په دې ډول یوسف د مصر په ټول هېواد باندې واک تر‌لاسه کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_45.mp3', '', 1761754199, 1761754199),
(50130, 'Genesis 41:46', 'Genesis', 41, 46, 'یوسف دېرش کلن ؤ چې د مصر د پاچا یعنې فرعون په خدمت کولو یې پیل وکړ. یوسف د فرعون د حضور څخه لاړ او په ټول مصر کې وګرځېد.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_46.mp3', '', 1761754199, 1761754199),
(50131, 'Genesis 41:47', 'Genesis', 41, 47, 'د اووه کالو پرېمانۍ په موده کې ځمکې ډېر زیات حاصلات ورکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_47.mp3', '', 1761754199, 1761754199),
(50132, 'Genesis 41:48', 'Genesis', 41, 48, 'په دې موده کې یوسف په مصر کې ټول خوراکي مواد راټول کړل او هغه یې په ښارونو کې ذخیره کړل او د هر ښار د شاوخوا ځمکو خوراکي مواد یې په هماغه ښار کې ذخیره کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_48.mp3', '', 1761754199, 1761754199),
(50133, 'Genesis 41:49', 'Genesis', 41, 49, 'یوسف لکه د بحیرې د شګو په شان ډېره زیاته غله ذخیره کړه او هغه دومره زیاته وه چې د حساب څخه وتلې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_49.mp3', '', 1761754199, 1761754199),
(50134, 'Genesis 41:50', 'Genesis', 41, 50, 'د قحطۍ د کلونو د راتللو څخه مخکې د اون د کاهن فوطي‌فارع لور اسنات یوسف ته دوه زامن وزېږول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_50.mp3', '', 1761754199, 1761754199),
(50135, 'Genesis 41:51', 'Genesis', 41, 51, 'یوسف د خپل مشر زوی نوم منسي کېښود، نو ځکه یې وویل: «خدای زما ټولې سختۍ او زما د پلار ټوله کورنۍ زما څخه هېره کړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_51.mp3', '', 1761754199, 1761754199),
(50136, 'Genesis 41:52', 'Genesis', 41, 52, 'او بیا د دوهم زوی نوم یې افرایم کېښود او ویې ویل: «دا ځکه چې خدای ماته په هغه وطن کې اولادونه راکړل چې زه په کې په تکلیف وم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_52.mp3', '', 1761754199, 1761754199),
(50137, 'Genesis 41:53', 'Genesis', 41, 53, 'نو هغه پرېماني چې د اووه کالو دپاره په مصر کې وه، پای ته ورسېدله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_53.mp3', '', 1761754199, 1761754199),
(50138, 'Genesis 41:54', 'Genesis', 41, 54, 'لکه څنګه چې یوسف ویلي وو، د قحطۍ اووه کاله پیل شول. په نورو ټولو هېوادونو کې قحطي وه، خو په ټول مصر کې غله وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_54.mp3', '', 1761754199, 1761754199),
(50139, 'Genesis 41:55', 'Genesis', 41, 55, 'کله چې مصریان وږي شول، نو د ډوډۍ دپاره یې فرعون ته فریاد وکړ. نو فرعون ټولو مصریانو ته وویل: «یوسف ته ورشئ او هرڅه چې تاسو ته وایي هغه وکړئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_55.mp3', '', 1761754199, 1761754199),
(50140, 'Genesis 41:56', 'Genesis', 41, 56, 'قحطي ډېره سخته شوه او په ټول هېواد کې خپره شوه، نو یوسف ګودامونه پرانیستل او په مصریانو باندې یې غله خرڅوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_56.mp3', '', 1761754199, 1761754199),
(50141, 'Genesis 41:57', 'Genesis', 41, 57, 'د ټولو هېوادونو خلک مصر ته راتلل چې د یوسف څخه غله واخلي، ځکه چې په ټوله دنیا کې سخته قحطي وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis41_verse_57.mp3', '', 1761754199, 1761754199),
(50142, 'Genesis 4:1', 'Genesis', 4, 1, 'آدم د حوا سره یوځای شو او حوا امیدواره شوه او زوی یې پیدا شو. حوا وویل: «زه به په هغه باندې قاین نوم کېږدم، ځکه چې هغه مې د څښتن په مرسته راوړ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis4_verse_1.mp3', '', 1761754199, 1761754199),
(50143, 'Genesis 4:2', 'Genesis', 4, 2, 'وروسته بیا د هغې بل زوی هابیل پیدا شو. هابیل شپون شو، خو قاین بزګر شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis4_verse_2.mp3', '', 1761754199, 1761754199),
(50144, 'Genesis 4:3', 'Genesis', 4, 3, 'لږه موده وروسته قاین د خپلې ځمکې د حاصلاتو یوه برخه د څښتن حضور ته نذرانه وړاندې کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis4_verse_3.mp3', '', 1761754199, 1761754199),
(50145, 'Genesis 4:4', 'Genesis', 4, 4, 'او هابیل هم خپل لومړنی زېږول شوی وری قرباني کړ او ډېره ښه برخه یې د څښتن حضور ته نذرانه وړاندې کړه. څښتن هابیل او د هغه نذرانه قبوله کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis4_verse_4.mp3', '', 1761754199, 1761754199),
(50146, 'Genesis 4:5', 'Genesis', 4, 5, 'خو قاین او د هغه نذرانه یې قبوله نه کړه، نو قاین ډېر په قهر شو او خپل سر یې ښکته واچاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis4_verse_5.mp3', '', 1761754199, 1761754199),
(50147, 'Genesis 4:6', 'Genesis', 4, 6, 'څښتن قاین ته وویل: «ته ولې په قهر شوې؟ او ولې دې خپل سر ښکته اچولی دی؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis4_verse_6.mp3', '', 1761754199, 1761754199),
(50148, 'Genesis 4:7', 'Genesis', 4, 7, 'که ښه کار دې کړی وای، ایا قبول شوی به نه وای؟ خو ښه دې نه دي کړي. اوس ګناه د دې موقعې په لټه کې ده چې په تا باندې حمله وکړي، هغه غواړي چې حکم درباندې وچلوي، خو ته باید په هغې باندې غالب شې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis4_verse_7.mp3', '', 1761754199, 1761754199),
(50149, 'Genesis 4:8', 'Genesis', 4, 8, 'قاین خپل ورور هابیل ته وویل: «راځه چې پټي ته لاړ شو.» هغه وخت چې دوی په پټي کې وو، قاین په خپل ورور هابیل باندې حمله وکړه او ویې واژه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis4_verse_8.mp3', '', 1761754199, 1761754199),
(50150, 'Genesis 4:9', 'Genesis', 4, 9, 'بیا څښتن د قاین څخه پوښتنه وکړه: «ستا ورور هابیل چېرته دی؟» هغه ځواب ورکړ: «زه څه خبر یم؟ ایا زه د خپل ورور ساتونکی یم؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis4_verse_9.mp3', '', 1761754199, 1761754199),
(50151, 'Genesis 4:10', 'Genesis', 4, 10, 'بیا څښتن وویل: «تا څه وکړل؟ خپل ورور دې وواژه او د هغه وینه په ځمکه باندې تویه شوه. اوس ستا د ورور وینه ماته فریاد کوي چې سزا درکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis4_verse_10.mp3', '', 1761754199, 1761754199),
(50152, 'Genesis 4:11', 'Genesis', 4, 11, 'زه به په تا باندې لعنت ووایم، ځکه چې تا هابیل وواژه او د هغه وینه دې په ځمکه باندې توی کړه. ته به هېڅکله په دې ځمکه باندې کښت ونه کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis4_verse_11.mp3', '', 1761754199, 1761754199),
(50153, 'Genesis 4:12', 'Genesis', 4, 12, 'که ته په دې ځمکه باندې خواري وکړې، هغه به ستا دپاره هېڅ حاصل درنه کړي. ته به بې‌کوره یې او خپل پاتې عمر به بې‌کوره او په سرګردانۍ کې تېروې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis4_verse_12.mp3', '', 1761754199, 1761754199),
(50154, 'Genesis 4:13', 'Genesis', 4, 13, 'قاین وویل: «ته ماته داسې سخته سزا راکوې چې زه یې د زغملو توان نه لرم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis4_verse_13.mp3', '', 1761754199, 1761754199),
(50155, 'Genesis 4:14', 'Genesis', 4, 14, 'ما نن د دې خاورې څخه شړې، چې خپل کور پرېږدم او ستا د حضور څخه لېرې لاړ شم. زه به بې‌کوره او سرګردانه ګرځم او هرڅوک چې ما پیدا کړي، نو وبه مې وژني.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis4_verse_14.mp3', '', 1761754199, 1761754199),
(50156, 'Genesis 4:15', 'Genesis', 4, 15, 'څښتن ځواب ورکړ: «نه! که څوک تا ووژني، زه به هغه ته اووه چنده سزا ورکړم.» نو څښتن په قاین باندې یوه نښه کېښودله چې دا به د هغه چا دپاره خبرداری وي څوک چې وغواړي قاین ووژني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis4_verse_15.mp3', '', 1761754199, 1761754199),
(50157, 'Genesis 4:16', 'Genesis', 4, 16, 'قاین د څښتن د حضور څخه لاړ. هغه په نود یعنې سرګردانۍ نومي ځای کې چې د عدن لمرخاته خواته پروت ؤ، ژوند اختیار کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis4_verse_16.mp3', '', 1761754199, 1761754199),
(50158, 'Genesis 4:17', 'Genesis', 4, 17, 'قاین د خپلې ښځې سره یوځای شو او زوی یې پیدا شو او په هغه باندې یې خنوخ نوم کېښود. هغه یو ښار جوړ کړ او د خپل زوی خنوخ نوم یې ورباندې کېښود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis4_verse_17.mp3', '', 1761754199, 1761754199),
(50159, 'Genesis 4:18', 'Genesis', 4, 18, 'د خنوخ څخه عیراد پیدا شو او د عیراد څخه محویاییل پیدا شو، د محویاییل څخه متوشاییل پیدا شو او د متوشاییل څخه لمک پیدا شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis4_verse_18.mp3', '', 1761754199, 1761754199),
(50160, 'Genesis 4:19', 'Genesis', 4, 19, 'لمک دوه ښځې وکړې، د یوې نوم عاده ؤ او د بلې نوم ظله ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis4_verse_19.mp3', '', 1761754199, 1761754199),
(50161, 'Genesis 4:20', 'Genesis', 4, 20, 'د عادې څخه یابال پیدا شو او هغه لومړنی کس ؤ چې کورني حیوانات یې روزل او په خېمو کې اوسېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis4_verse_20.mp3', '', 1761754199, 1761754199),
(50162, 'Genesis 4:21', 'Genesis', 4, 21, 'د هغه د ورور نوم یوبال ؤ او هغه لومړنی کس ؤ چې رباب او شپېلۍ به یې وهله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis4_verse_21.mp3', '', 1761754199, 1761754199),
(50163, 'Genesis 4:22', 'Genesis', 4, 22, 'د ظلې څخه هم توبل قاین پیدا شو او هغه اهنګر ؤ او د برنجو او اوسپنې څخه به یې د کار هر ډول وسایل جوړول. نعمه د توبل قاین خور وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis4_verse_22.mp3', '', 1761754199, 1761754199),
(50164, 'Genesis 4:23', 'Genesis', 4, 23, 'یوه ورځ لمک خپلو ښځو ته وویل: ای عادې او ظلې زما خبرې واورئ ما یو ځوان سړی وژلی ځکه زه یې وم وهلی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis4_verse_23.mp3', '', 1761754199, 1761754199),
(50165, 'Genesis 4:24', 'Genesis', 4, 24, 'که بدل د قاین اخیستل کیږي اووه وارې نو د لمک به اخیستی شي اووه اویا وارې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis4_verse_24.mp3', '', 1761754199, 1761754199),
(50166, 'Genesis 4:25', 'Genesis', 4, 25, 'آدم بیا د خپلې ښځې سره یوځای شو او زوی یې پیدا شو او د هغه نوم یې شیت کېښود. هغې وویل: «دا ځکه چې خدای ماته د هابیل په ځای چې د خپل ورور قاین له لاسه ووژل شو، بل زوی راکړ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis4_verse_25.mp3', '', 1761754199, 1761754199),
(50167, 'Genesis 4:26', 'Genesis', 4, 26, 'د شیت زوی پیدا شو او د هغه نوم یې انوش کېښود. په همدې وخت کې خلکو د څښتن عبادت کول پیل کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis4_verse_26.mp3', '', 1761754199, 1761754199),
(50168, 'Isaiah 16:1', 'Isaiah', 16, 1, 'هغه پاچا ته چې د صهیون په غره پاچاهي کوي، له سالع د دښتې له لارې وري د باج په توګه ورولېږئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah16_verse_1.mp3', '', 1761754199, 1761754199),
(50169, 'Isaiah 16:2', 'Isaiah', 16, 2, 'د موآب خلک د ارنون د سیند په ګودر کې انتظار کوي او د هغو مرغیو په شان چې د خپلو ځالو څخه شړل شوې وي، ځي او راځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah16_verse_2.mp3', '', 1761754199, 1761754199),
(50170, 'Isaiah 16:3', 'Isaiah', 16, 3, 'هغوی د یهودا خلکو ته وایي: «مونږ ته مشوره راکړئ چې څه وکړو. د هغې ونې په شان چې د غرمې په ګرمۍ کې یخ سیوری کوي زمونږ ساتنه وکړئ او پرېږدئ چې ستاسو د سیوري لاندې ارام وکړو. مونږ مهاجر یو، مونږ په یو خوندي ځای کې پټ کړئ او دښمنانو ته مو په لاس ورنه کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah16_verse_3.mp3', '', 1761754199, 1761754199),
(50171, 'Isaiah 16:4', 'Isaiah', 16, 4, 'مونږ ته اجازه راکړئ چې ستاسو په وطن کې پاتې شو. له هغو خلکو مو وساتئ چې غواړي مونږ له منځه یوسي.» ظلم او ویجاړي به پای ته ورسیږي او څوک چې وطن ورانوي هغه به ورک شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah16_verse_4.mp3', '', 1761754199, 1761754199),
(50172, 'Isaiah 16:5', 'Isaiah', 16, 5, 'هغه وخت به د داود له اولادې یو کس پاچا شي او هغه به په تلپاتې مینې او وفادارۍ سره په خلکو باندې پاچاهي کوي. د هغه قضاوت به د عدالت په بنیاد ولاړ وي او پرته له ځنډه به انصاف عملي کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah16_verse_5.mp3', '', 1761754199, 1761754199),
(50173, 'Isaiah 16:6', 'Isaiah', 16, 6, 'مونږ اورېدلي چې د موآب خلک څومره مغرور دي. مونږ پوهېږو چې هغوی سپین سترګي او کبرجن خلک دي. هغوی ډېرې لافې وهي، خو د هغوی لافې بېځایه دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah16_verse_6.mp3', '', 1761754199, 1761754199),
(50174, 'Isaiah 16:7', 'Isaiah', 16, 7, 'په دې خاطر، د موآب ټول خلک په خپل حال باندې ژاړي. کله چې هغوی ته هغه د ممیزو کلچې ور په یاد شي چې د قیرحارس په ښار کې به یې خوړلې، نو هغوی به انګولا او ژړا کوي. هغوی د پښو نه لوېدلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah16_verse_7.mp3', '', 1761754199, 1761754199),
(50175, 'Isaiah 16:8', 'Isaiah', 16, 8, 'حشبون ته نژدې کروندې، د سبمه د انګورو باغونه وچ شوي دي او د نورو قومونو حکمرانانو د انګورو تاکونه پرېکړې دي. په یو وخت کې د دې تاکونو څانګې د یعزیر تر ښاره او ختیځې خواته په دښته کې او لوېدیځې خواته د ارام بحیرې تر بلې غاړې پورې رسېدلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah16_verse_8.mp3', '', 1761754199, 1761754199),
(50176, 'Isaiah 16:9', 'Isaiah', 16, 9, 'اوس زه د سبمه د تاکونو پسې ژاړم، لکه څنګه چې د یعزیر خلک هم ژاړي. زما اوښکې د حشبون او العاله دپاره د سېلاب په شان توییږي. ځکه چې د اوړي مېوې او غلې دانې نشته چې خلک د خوشحالۍ چیغې ووهي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah16_verse_9.mp3', '', 1761754199, 1761754199),
(50177, 'Isaiah 16:10', 'Isaiah', 16, 10, 'په هغو حاصلخېزو ځمکو کې هېڅ خوشحالي او خندا نه لیدل کیږي. د انګورو په باغونو کې نه څوک له خوښۍ نه چیغې وهي او نه څوک سندرې وایي. هېڅوک انګور د زبېښلو دپاره تر پښو لاندې نه کوي، ما د خوشحالۍ اوازونه غلي کړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah16_verse_10.mp3', '', 1761754199, 1761754199),
(50178, 'Isaiah 16:11', 'Isaiah', 16, 11, 'نو زما زړه د موآب او قیرحارس دواړو دپاره د غم رباب وهي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah16_verse_11.mp3', '', 1761754199, 1761754199),
(50179, 'Isaiah 16:12', 'Isaiah', 16, 12, 'د موآب خلک سیمه ایزو او لویو بتخانو ته د دعا دپاره ځي، خو هغوی هسې ځانونه ستړي کوي ځکه چې دا هغوی ته هېڅ ګټه نه لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah16_verse_12.mp3', '', 1761754199, 1761754199),
(50180, 'Isaiah 16:13', 'Isaiah', 16, 13, 'دا هغه پیغام ؤ چې څښتن پخوا د موآب د خلکو په اړه ورکړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah16_verse_13.mp3', '', 1761754199, 1761754199),
(50181, 'Isaiah 16:14', 'Isaiah', 16, 14, 'اوس څښتن وایي: «په پوره درې کالو کې به د موآب شان او شوکت له منځه لاړ شي. د موآب له ډېرو خلکو نه به یوازې یو څو تنه ژوندي پاتې شي او هغوی به هم ډېر کمزوري وي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah16_verse_14.mp3', '', 1761754199, 1761754199),
(50182, 'Isaiah 21:1', 'Isaiah', 21, 1, 'دا پیغام د بحیرې د غاړې د دښتې په هکله دی: لښکرې به له جنوبي دښتې د بوړبوړکۍ په شان د یو وېروونکي وطن نه په بابل حمله وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah21_verse_1.mp3', '', 1761754199, 1761754199),
(50183, 'Isaiah 21:2', 'Isaiah', 21, 2, 'ما یوه هیبتناکه رویا ولیدله، چې خاینان خیانت کوي او تباه کوونکي تباهي کوي. ای د عیلام لښکرو، حمله وکړئ! ای د ماد لښکرو، ښارونه کلابند کړئ! کوم درد او غم چې بابل رسولی دی، خدای به هغه پای ته ورسوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah21_verse_2.mp3', '', 1761754199, 1761754199),
(50184, 'Isaiah 21:3', 'Isaiah', 21, 3, 'نو څه چې مې په رویا کې ولیدل او واورېدل، ډېر ووېرېدم. ټول ځان مې په داسې درد اخته شو لکه په ښځې چې د لنګون په وخت کې راځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah21_verse_3.mp3', '', 1761754199, 1761754199),
(50185, 'Isaiah 21:4', 'Isaiah', 21, 4, 'زړه مې درزیږي او له وېرې رپېږم. زه د یو ښه او ارام ماښام د راتللو په هیله وم، خو هغه ماته پرته له وېرې بل هېڅ رانه وړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah21_verse_4.mp3', '', 1761754199, 1761754199),
(50186, 'Isaiah 21:5', 'Isaiah', 21, 5, 'په رویا کې مې ولیدل چې مېلمستیا تیاره ده او د بابلیانو د ناستې دپاره دسترخوانونه غوړېدلي دي. ټول د خوړلو او څښلو په حال کې دي، چې ناڅاپه یو اواز پورته شو: «ای افسرانو پورته شئ او خپل سپرونه تیار کړئ!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah21_verse_5.mp3', '', 1761754199, 1761754199),
(50187, 'Isaiah 21:6', 'Isaiah', 21, 6, 'بیا څښتن ماته داسې وویل: «لاړ شه، یو پهره دار ودروه او هغه ته ووایه: ‹هرڅه چې دې ولیدل د هغه راپور راکړه.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah21_verse_6.mp3', '', 1761754199, 1761754199),
(50188, 'Isaiah 21:7', 'Isaiah', 21, 7, 'که هغه داسې کسان وویني چې په دوه اسونو لرونکو جنګي ګاډیو کې راروان وي او یا داسې عسکر چې په خرو او اوښانو باندې سپاره وي، نو په ډېر ځیر سره دې هغوی ته پام وکړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah21_verse_7.mp3', '', 1761754199, 1761754199),
(50189, 'Isaiah 21:8', 'Isaiah', 21, 8, 'پهره دار غږ وکړ: «باداره، ما شپه او ورځ په ټاکلي ځای باندې پهره کوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah21_verse_8.mp3', '', 1761754199, 1761754199),
(50190, 'Isaiah 21:9', 'Isaiah', 21, 9, 'اوس هغوی راغلل! خلک په جوړه اسونو لرونکو جنګي ګاډیو باندې سپاره راروان دي.» په دې وخت کې پهره دار خبر ورکړ او ویې ویل: «بابل سقوط وکړ! د بابل ټول بتان په ځمکه لوېدلي او ټوټې ټوټې شوي دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah21_verse_9.mp3', '', 1761754199, 1761754199),
(50191, 'Isaiah 21:10', 'Isaiah', 21, 10, 'ای زما خلکو اسراییلو، تاسو د غنمو په شان غوبل او باد شوي یئ، خو اوس څه چې ما له مطلق قادر څښتن څخه اورېدلي دي تاسو ته اعلانوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah21_verse_10.mp3', '', 1761754199, 1761754199),
(50192, 'Isaiah 21:11', 'Isaiah', 21, 11, 'دا هغه پیغام دی چې د ادوم په هکله دی. یو څوک ماته د ادوم څخه اواز کوي: «پهره داره، دا شپه به کله سبا کیږي؟ دا شپه به کله پای ته رسیږي؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah21_verse_11.mp3', '', 1761754199, 1761754199),
(50193, 'Isaiah 21:12', 'Isaiah', 21, 12, 'ما ځواب ورکړ: «شپه به تېره او سهار شي، خو شپه بیا راځي. که ته نوره پوښتنه لرې، نو بېرته راشه او پوښتنه وکړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah21_verse_12.mp3', '', 1761754199, 1761754199),
(50194, 'Isaiah 21:13', 'Isaiah', 21, 13, 'دا د عربستان په هکله پیغام دی. ای د ددان خلکو، تاسو چې د خپلو کاروانونو دپاره د عربستان په شاړو دښتو کې خېمې ودروئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah21_verse_13.mp3', '', 1761754199, 1761754199),
(50195, 'Isaiah 21:14', 'Isaiah', 21, 14, 'هغو خلکو ته چې تږي دي او تاسو ته راځي اوبه ورکړئ. ای د تیما خلکو، مهاجرو ته خواړه ورکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah21_verse_14.mp3', '', 1761754199, 1761754199),
(50196, 'Isaiah 21:15', 'Isaiah', 21, 15, 'ځکه چې هغوی د تورو او په لیندو کې د غشو له ګوزارونو او تودې جګړې څخه تښتېدلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah21_verse_15.mp3', '', 1761754199, 1761754199),
(50197, 'Isaiah 21:16', 'Isaiah', 21, 16, 'بیا څښتن ماته داسې وویل: «پوره په یو کال کې به د قیدار ټول شان او شوکت پای ته ورسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah21_verse_16.mp3', '', 1761754199, 1761754199),
(50198, 'Isaiah 21:17', 'Isaiah', 21, 17, 'د قیدار د لښکرو له غشو ویشتونکو څخه به یوازې یو څو تنه پاتې شي. دا زه، یعنې د اسراییلو څښتن خدای تاسو ته وایم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah21_verse_17.mp3', '', 1761754199, 1761754199),
(50199, 'Songofsongs 2:1', 'Songofsongs', 2, 1, 'زۀ لکه د شارون د ګلاب په شان يمه، او په پټو کښې د لاله د ګل په شان يمه. محبوب', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs2_verse_1.mp3', '', 1761754199, 1761754199),
(50200, 'Songofsongs 2:2', 'Songofsongs', 2, 2, 'لکه چې په ازغو کښې د لاله ګل وينه، زما محبوبه د پېغلو په مينځ کښې داسې وينه. محبوبه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs2_verse_2.mp3', '', 1761754199, 1761754199),
(50201, 'Songofsongs 2:3', 'Songofsongs', 2, 3, 'لکه د سيب د ونې په شان په ځنګل کښې زما جانان د نورو زلمو په مينځ کښې دېنه. د هغۀ د سورى لاندې په کښېناستو ډېره خوشحالېږمه، او زما په خولۀ د هغۀ مېوې خوږې لګيږينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs2_verse_3.mp3', '', 1761754199, 1761754199),
(50202, 'Songofsongs 2:4', 'Songofsongs', 2, 4, 'هغۀ زۀ د خپل ځان سره د مېلمنو هال ته روانه کړمه، او زۀ يې په خپله مينه کښې ونغښتلمه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs2_verse_4.mp3', '', 1761754199, 1761754199),
(50203, 'Songofsongs 2:5', 'Songofsongs', 2, 5, 'د کشمشو سره يې ما ته طاقت راکړلو، او د سيوانو سره يې زۀ تازه کړمه، ځکه د مينې په وجه مړاوې شوې ومه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs2_verse_5.mp3', '', 1761754199, 1761754199),
(50204, 'Songofsongs 2:6', 'Songofsongs', 2, 6, 'د هغۀ ګس لاس زما د سر لاندې وونه، او د هغۀ ښى لاس ځانته راغاړه ايستمه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs2_verse_6.mp3', '', 1761754199, 1761754199),
(50205, 'Songofsongs 2:7', 'Songofsongs', 2, 7, 'اے د يروشلم جينکو، ما سره ټينګه وعده وکړئ، ترڅو چې مونږ پراتۀ يونه مونږ به نۀ په عذابوئينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs2_verse_7.mp3', '', 1761754199, 1761754199),
(50206, 'Songofsongs 2:8', 'Songofsongs', 2, 8, 'وګوره، چې جانان مې راروان دېنه، هغه په غرونو راخېژينه، او په غونډو ټوپونه وهينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs2_verse_8.mp3', '', 1761754199, 1761754199),
(50207, 'Songofsongs 2:9', 'Songofsongs', 2, 9, 'زما جانان لکه هوسۍ او يا د ځوان هوسۍ په شان دېنه، وګوره هغه اوس زمونږ د دېوال شاته ولاړ دېنه، هلته د کړکۍ د جال نه دننه کوټې ته ګورينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs2_verse_9.mp3', '', 1761754199, 1761754199),
(50208, 'Songofsongs 2:10', 'Songofsongs', 2, 10, 'زما جانان ما ته ووئيل، محبوب ”زما محبوبې، راپاڅه، ښائسته محبوبې، راځه ما سره لاړه شه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs2_verse_10.mp3', '', 1761754199, 1761754199),
(50209, 'Songofsongs 2:11', 'Songofsongs', 2, 11, 'وګوره، ژمې تېر شو بارانونه ودرېدل او بس شونه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs2_verse_11.mp3', '', 1761754199, 1761754199),
(50210, 'Songofsongs 2:12', 'Songofsongs', 2, 12, 'په زمکه ګلونه راښکاره شونه، د سندرو وئيلو موسم رارسېدلے دېنه، زمونږ په مُلک کښې د ګوګوشتکو آوازونه اورېدلے کيږينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs2_verse_12.mp3', '', 1761754199, 1761754199);